#ifndef LOG_FORMATTER_H
#define LOG_FORMATTER_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

struct log_entry {
    char timestamp[32];
    char level[16];
    char content[256];
};

int format_log_messages(struct log_entry *logs[], int log_count, char *output_buffer, int buffer_size);

